    "explain_vi": "「Vておく」 diễn tả việc sẽ làm sẵn trước để chuẩn bị cho buổi tối (「予約しておくよ」: để anh đặt trước cho nhé). Bẫy cực hay nhầm: 「予約してあるね」 là trạng thái ĐÃ đặt sẵn từ trước rồi (mâu thuẫn vì sau đó chồng vẫn hỏi 「19時からで大丈夫？」); 「予約してね」 lại nhờ ngược vợ; 「予約しようよ」 là rủ cả hai cùng làm."
