    "explain_vi": "「Vます(bỏ ます) + やすい」 → 「使いやすい」 (dễ sử dụng), phù hợp ngữ cảnh gợi ý ưu điểm tích cực của cuốn từ điển. Bẫy: 「使いでもいい」 sai ngữ pháp (phải chia thể て 「使ってもいい」); 「使いそうだ」 (có vẻ sắp dùng - vô nghĩa); 「使いすぎる」 (dùng quá mức - nghĩa tiêu cực)."
