    "sentence_vi": "Tiền bối: “Nishida này, thầy đã xem cuốn tạp chí có đăng bài luận văn của cậu và khen là cậu cố gắng tốt lắm đấy.” — Nishida: “Hả, anh ơi, thật sao ạ?”",
