    "sentence_vi": "Sinh viên: “Em vô cùng xin lỗi. Quyển sách tuần trước em được thầy Honda cho mượn, em lại lỡ để quên ở nhà mất rồi…” — Thầy Honda: “À, để ngày mai cũng không sao đâu.”",
