    "sentence_vi": "Vì nhà tôi mở tiệm bánh mì nên ngay cả ngày nghỉ tôi cũng thường bị bố mẹ bắt phụ dọn dẹp cửa hàng, hầu như chẳng được chơi với bạn bè.",
