    "sentence_vi": "Tôi rất thích nhảy và luyện tập mỗi ngày. Có nhiều người nhảy giỏi hơn tôi, nhưng riêng tình yêu dành cho nhảy múa thì tôi không thua kém bất kỳ ai.",
