    "sentence_vi": "Tanaka: “Tớ mới bắt đầu chơi tennis thôi, cậu có biết chơi tennis không Yamashita?” — Yamashita: “Ừ cũng được. Trước đây ở trường tớ từng tham gia câu lạc bộ tennis rồi.”",
